SELECT (SELECT score FROM male_icu_patients_95th_percentile) AS 95th_percentile_score, (SELECT score FROM male_icu_patients_top_quartile) AS top_quartile_score, (SELECT COUNT(*) FROM male_icu_patients) AS total_patients, (SELECT COUNT(*) FROM male_icu_patients WHERE l.value < 65) AS hypotension_patients, (SELECT COUNT(*) FROM male_icu_patients WHERE l.value > 100) AS tachycardia_patients, (SELECT SUM(i.length_of_stay) FROM male_icu_patients i JOIN icustays s ON i.subject_id = s.subject_id) AS total_icu_los, (SELECT COUNT(*) FROM male_icu_patients WHERE d.deathtime IS NOT NULL) AS mortality_patients FROM labevents l JOIN diagnoses_icd d ON l.subject_id = d.subject_id AND l.hadm_id = d.hadm_id;